// Trim, lowercase the email, and drop the obvious bots before they cost an
// LLM call. The honeypot is a hidden form field a human never fills in.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  if ((b.website ?? '').trim() !== '') continue;          // honeypot tripped
  const email = (b.email ?? '').trim().toLowerCase();
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) continue;
  out.push({ json: {
    name: (b.name ?? '').trim(),
    email,
    brand: (b.brand ?? '').trim(),
    message: (b.message ?? '').trim().slice(0, 4000),
    budget: (b.budget ?? '').trim(),
    submittedAt: new Date().toISOString()
  }});
}
return out;

// Merge the model's verdict back onto the enquiry. If the model failed or
// returned something unparseable, fall back to "unclear" and route to the
// human. Losing a lead to a bad JSON parse is the worst outcome here.
const out = [];
for (const item of $input.all()) {
  const enquiry = $('Clean and drop bots').first().json;
  let verdict = { service: 'unclear', fit: 'possible', urgency: 'normal', reason: 'classifier unavailable' };
  try {
    const raw = item.json.message?.content ?? item.json.content ?? item.json;
    verdict = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) { /* keep the fallback */ }
  out.push({ json: { ...enquiry, ...verdict } });
}
return out;

